using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
public static class ActualRiderFeetSetup {
 const string Folder="Assets/Characters/SledFeet";
 [InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=Run;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=Run;};}
 public static bool Attach(GameObject rider,bool woman){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+(woman?"/SaqeeraOriginalFeet.prefab":"/MuflehOriginalFeet.prefab"));if(!prefab)return false;var previous=rider.transform.Find("Visible sandal feet");if(previous)previous.gameObject.SetActive(false);if(!rider.transform.Find("Original character feet")){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab,rider.scene);g.name="Original character feet";g.transform.SetParent(rider.transform,false);}return true;}
 static void Build(bool woman,System.Text.StringBuilder report){string label=woman?"Traditional Dress":"Desert Robe";string folder="Assets/Resources/CharacterCollection/"+label;var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Directory.GetFiles(folder,"*.fbx").Single()));try{
 var renderer=source.GetComponentsInChildren<SkinnedMeshRenderer>(true).OrderByDescending(r=>r.sharedMesh.vertexCount).First();var baked=new Mesh();renderer.BakeMesh(baked);var v=baked.vertices;for(int i=0;i<v.Length;i++)v[i]=source.transform.InverseTransformPoint(renderer.transform.TransformPoint(v[i]));float min=v.Min(x=>x.y),max=v.Max(x=>x.y),scale=1.65f/(max-min);float cutoff=min+(max-min)*.105f;
 var triangles=new List<int>();for(int sub=0;sub<baked.subMeshCount;sub++){var all=baked.GetTriangles(sub);for(int i=0;i<all.Length;i+=3)if(v[all[i]].y<cutoff&&v[all[i+1]].y<cutoff&&v[all[i+2]].y<cutoff){triangles.Add(all[i]);triangles.Add(all[i+1]);triangles.Add(all[i+2]);}}
 if(triangles.Count<30)throw new Exception("No source feet: "+label);
 var used=triangles.Distinct().ToArray();float xCentre=(used.Min(i=>v[i].x)+used.Max(i=>v[i].x))*.5f,zCentre=(used.Min(i=>v[i].z)+used.Max(i=>v[i].z))*.5f;float length=(used.Max(i=>v[i].z)-used.Min(i=>v[i].z))*scale;float width=(used.Max(i=>v[i].x)-used.Min(i=>v[i].x))*scale;scale*=Mathf.Min(1,.29f/Mathf.Max(.001f,length),(woman?.28f:.33f)/Mathf.Max(.001f,width));
 var uv=baked.uv;var positions=new Vector3[used.Length];var tex=new Vector2[used.Length];var remap=new Dictionary<int,int>();for(int i=0;i<used.Length;i++){int k=used[i];remap[k]=i;positions[i]=new Vector3((v[k].x-xCentre)*scale,(v[k].y-min)*scale+.055f,(v[k].z-zCentre)*scale+.43f);if(uv.Length==v.Length)tex[i]=uv[k];}
 var mesh=new Mesh(){name=(woman?"Saqeera":"Mufleh")+" original feet",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.vertices=positions;mesh.uv=tex;mesh.triangles=triangles.Select(i=>remap[i]).ToArray();mesh.RecalculateBounds();mesh.RecalculateNormals();string basePath=Folder+(woman?"/SaqeeraOriginalFeet":"/MuflehOriginalFeet");AssetDatabase.CreateAsset(mesh,basePath+".asset");var root=new GameObject("Original character feet");root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(folder+"/Clothing.mat");PrefabUtility.SaveAsPrefabAsset(root,basePath+".prefab");UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(baked);report.AppendLine(label+": extracted "+triangles.Count/3+" triangles directly from original FBX with original Clothing texture; feet sole .055m; front within .575m sled rim");
 }finally{UnityEngine.Object.DestroyImmediate(source);}}
 static void Run(){if(EditorApplication.isPlayingOrWillChangePlaymode||File.Exists("work/original-character-feet-v1.txt"))return;try{var report=new System.Text.StringBuilder();Build(false,report);Build(true,report);var scene=SceneManager.GetSceneByPath("Assets/Scenes/Demo.unity");bool opened=!scene.isLoaded;if(opened)scene=EditorSceneManager.OpenScene("Assets/Scenes/Demo.unity",OpenSceneMode.Additive);foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray())if(t.name=="Desert_Robe_Character_ROOT"||t.name=="Traditional_Woman_ROOT")Attach(t.gameObject,t.name=="Traditional_Woman_ROOT");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);if(opened)EditorSceneManager.CloseScene(scene,true);AssetDatabase.SaveAssets();File.WriteAllText("work/original-character-feet-v1.txt",report.ToString());}catch(Exception e){Debug.LogException(e);File.WriteAllText("work/original-character-feet-error.txt",e.ToString());}}
}
